27	 */
28	@Repository
29	public class DispatchRepository {
30	
31	    private final JdbcTemplate jdbc;
32	
33	    public DispatchRepository(JdbcTemplate jdbc) {
34	        this.jdbc = jdbc;
35	    }
36	
37	    private static final RowMapper<CurtailOrder> ORDER_MAPPER = (rs, n) -> {
38	        CurtailOrder o = new CurtailOrder();
39	        o.setId(rs.getLong("id"));
