49	        o.setReceivedAt(rs.getTimestamp("received_at").toInstant());
50	        Timestamp settled = rs.getTimestamp("settled_at");
51	        o.setSettledAt(settled == null ? null : settled.toInstant());
52	        return o;
53	    };
54	
55	    private static final RowMapper<DispatchCycle> CYCLE_MAPPER = (rs, n) -> {
56	        DispatchCycle c = new DispatchCycle();
57	        c.setId(rs.getLong("id"));
58	        c.setOrderId(rs.getLong("order_id"));
59	        c.setCycleNo(rs.getInt("cycle_no"));
60	        c.setDispatchedAt(rs.getTimestamp("dispatched_at").toInstant());
61	        c.setDueAt(rs.getTimestamp("due_at").toInstant());
62	        return c;
63	    };
64	
65	    private static final RowMapper<Allocation> ALLOCATION_MAPPER = (rs, n) -> {
66	        Allocation a = new Allocation();
67	        a.setId(rs.getLong("id"));
68	        a.setOrderId(rs.getLong("order_id"));
69	        a.setCycleNo(rs.getInt("cycle_no"));
70	        a.setTurbineId(rs.getLong("turbine_id"));
