 */
@SpringBootTest
class DispatchFlowIntegrationTest extends AbstractIntegrationTest {

    @Autowired
    private DispatchService dispatchService;

    @BeforeEach
    void setUp() {
        resetDb();
        pinClock(10, 0, 0);
    }

    @Test
    @DisplayName("接收即分摊：恰等全场可用出力时不降机")
