import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.function.IntFunction;

import com.example.starter.dto.PlanPublishRequest;

/**
 * 日前计划测试夹具：快速构造完整 96 段 × 机组计划，支持单段改写、缺段与重复段。
