 * @param farmCode        风场编码
 * @param planDate        UTC 日期 yyyy-MM-dd
 * @param expectedVersion 期望的当前版本号；首次发布传 0，其后传当前版本号（成功发布后 +1）
 * @param opTime          请求精确时刻（UTC，ISO-8601），作为发布时刻，参与指纹
 * @param segments        96 个时段（每段序号 0-95 且各机组计划唯一）
 */
public record PlanPublishRequest(
        @NotBlank String requestId,
        @NotBlank String farmCode,
        @NotBlank String planDate,
        @NotNull @PositiveOrZero Integer expectedVersion,
        @NotNull Instant opTime,
        @NotNull @Size(min = 96, max = 96) @Valid List<SegmentInput> segments) {

    /** 单个半开时段：segmentIndex 为 0-95，entries 为该段每台机组计划（机组不得重复）。 */
    public record SegmentInput(
            @NotNull @PositiveOrZero Integer segmentIndex,
            @NotEmpty @Valid List<EntryInput> entries) {
    }

